UPDATE businesses SET description = 'Underhill Corporate Solutions is an SMME based in Sunnyside, Pretoria, operating as a socio-economic research and business consulting company across Southern Africa. The team carries out socio-economic research and surveys, development-programme monitoring and evaluation, economic-impact assessment and econometric analysis, and data capturing and analysis for clients in both the public and private sectors.

Beyond research, the company supports business and institutional development, regional development, and trade and investment promotion, alongside education and training services. It holds Level 1 B-BBEE status and applies specialised software, including EViews, Stata, SAS, CSPro and SPSS, for socio-economic modelling and analysis, giving clients a technically grounded basis for development planning and policy decisions across the region.', description_enriched_at = datetime('now') WHERE slug = 'underhill-corporate-solutions-candlewoods-estate' AND description = 'Underhill Corporate Solutions is a business consultancy in Sunnyside specialising in socio-economic research, development-programme monitoring and evaluation, data capturing and analysis, and economic impact assessment for clients across Southern Africa.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
