UPDATE businesses SET description = 'Vista The Blyde is the on-site restaurant at The Blyde Crystal Lagoon resort in Savannah Country Estate, part of the MINT Hotels group, serving as a foodie destination for guests and visitors in Pretoria East. The menu runs from breakfast dishes such as eggs Benedict and shakshuka through to salads, sandwiches and wraps, burgers, wood-fired pizzas, pasta and seafood.

Diners can also choose from steaks and grilled meats, including fillet, rump, ribs and lamb, alongside desserts, milkshakes and sharing platters. Breakfast service starts at 07:00, and the restaurant covers breakfast, lunch and dinner, with delivery available to resort guests. Vista The Blyde trades Monday to Saturday from 07:00 to 22:30, within the Savannah Country Estate development in Pretoria East.', description_enriched_at = datetime('now') WHERE slug = 'vista-the-blyde-blyde-riverwalk-estate' AND description = 'Vista The Blyde is a restaurant at The Blyde Crystal Lagoon in Savannah Country Estate serving wood-fired pizzas, pastas, burgers, signature grills, seafood and breakfast with views over the lagoon.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
